// n8n Webhook: body may be at $input.item.json (root) or $input.item.json.body
const body = ($input.item.json && $input.item.json.body != null) ? $input.item.json.body : ($input.item.json || {});
const schema = body.schema || [];
const recordCount = body.recordCount || 100;
const exportFormat = body.exportFormat || 'csv';
const sampleData = body.sampleData || null;

// Validate inputs
if (!schema || schema.length === 0) {
  return [{
    json: {
      success: false,
      error: 'Schema is required and must contain at least one field'
    }
  }];
}

if (recordCount < 1 || recordCount > 10000) {
  return [{
    json: {
      success: false,
      error: 'Record count must be between 1 and 10,000'
    }
  }];
}

// ============================================
// STEP 1: Use fieldPatterns from request, or extract from sampleData
// ============================================
let fieldPatterns = {};

if (body.fieldPatterns && typeof body.fieldPatterns === 'object' && Object.keys(body.fieldPatterns).length > 0) {
  fieldPatterns = body.fieldPatterns;
  console.log('✅ Simple Generator: Using fieldPatterns from request');
} else if (sampleData && Array.isArray(sampleData) && sampleData.length > 0) {
  console.log('✅ Simple Generator: sampleData provided, extracting patterns from ALL fields...');
  sampleData.forEach(record => {
    Object.keys(record).forEach(fieldName => {
      const value = record[fieldName];
      if (value == null || value === '') return;
      if (!fieldPatterns[fieldName]) fieldPatterns[fieldName] = [];
      if (typeof value === 'string' || typeof value === 'number') {
        const stringValue = String(value).trim();
        if (stringValue && !fieldPatterns[fieldName].includes(stringValue)) {
          fieldPatterns[fieldName].push(stringValue);
        }
      }
    });
  });
  console.log('✅ Patterns extracted for fields:', Object.keys(fieldPatterns));
} else {
  console.log('ℹ️ Simple Generator: No sampleData/fieldPatterns provided, using generic generators (Schema Builder mode)');
}

// ============================================
// STEP 2: Generic pattern-based value generator
// ============================================
function getPatternValue(fieldName) {
  if (fieldPatterns[fieldName] && fieldPatterns[fieldName].length > 0) {
    return fieldPatterns[fieldName][Math.floor(Math.random() * fieldPatterns[fieldName].length)];
  }
  const fieldNameLower = fieldName.toLowerCase();
  for (const patternFieldName in fieldPatterns) {
    if (patternFieldName.toLowerCase() === fieldNameLower && fieldPatterns[patternFieldName].length > 0) {
      return fieldPatterns[patternFieldName][Math.floor(Math.random() * fieldPatterns[patternFieldName].length)];
    }
  }
  for (const patternFieldName in fieldPatterns) {
    const patternFieldNameLower = patternFieldName.toLowerCase();
    if ((fieldNameLower.includes(patternFieldNameLower) || patternFieldNameLower.includes(fieldNameLower)) && fieldPatterns[patternFieldName].length > 0) {
      return fieldPatterns[patternFieldName][Math.floor(Math.random() * fieldPatterns[patternFieldName].length)];
    }
  }
  return null;
}

// ============================================
// STEP 3: Data generation functions (fallbacks)
// ============================================
const genericFirstNames = ['James', 'Mary', 'John', 'Patricia', 'Robert', 'Jennifer', 'Michael', 'Linda', 'William', 'Elizabeth', 'David', 'Barbara', 'Richard', 'Susan', 'Joseph', 'Jessica', 'Thomas', 'Sarah', 'Charles', 'Karen'];
const genericLastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez', 'Hernandez', 'Lopez', 'Gonzalez', 'Wilson', 'Anderson', 'Thomas', 'Taylor', 'Moore', 'Jackson', 'Martin'];
const genericCities = ['New York', 'Los Angeles', 'Chicago', 'Houston', 'Phoenix', 'Philadelphia', 'San Antonio', 'San Diego', 'Dallas', 'San Jose'];

const generators = {
  firstName: () => {
    const v = getPatternValue('first_name') || getPatternValue('firstName') || getPatternValue('firstname');
    if (v) return v;
    return genericFirstNames[Math.floor(Math.random() * genericFirstNames.length)];
  },
  lastName: () => {
    const v = getPatternValue('last_name') || getPatternValue('lastName') || getPatternValue('lastname');
    if (v) return v;
    return genericLastNames[Math.floor(Math.random() * genericLastNames.length)];
  },
  email: () => {
    const first = generators.firstName().toLowerCase();
    const last = generators.lastName().toLowerCase();
    const domains = ['gmail.com', 'yahoo.com', 'outlook.com', 'example.com', 'email.com'];
    return `${first}.${last}@${domains[Math.floor(Math.random() * domains.length)]}`;
  },
  phone: () => {
    const area = Math.floor(Math.random() * 900) + 100;
    const prefix = Math.floor(Math.random() * 900) + 100;
    const line = Math.floor(Math.random() * 9000) + 1000;
    return `(${area}) ${prefix}-${line}`;
  },
  address: () => {
    const num = Math.floor(Math.random() * 9999) + 1;
    const streets = ['Main St', 'Oak Ave', 'Maple Dr', 'Cedar Ln', 'Pine Rd', 'Elm St', 'Washington Blvd', 'Park Ave'];
    return `${num} ${streets[Math.floor(Math.random() * streets.length)]}`;
  },
  city: () => {
    const v = getPatternValue('city') || getPatternValue('city_of_purchase') || getPatternValue('cityName');
    if (v) return v;
    return genericCities[Math.floor(Math.random() * genericCities.length)];
  },
  company: () => {
    const v = getPatternValue('company') || getPatternValue('company_name') || getPatternValue('organization');
    if (v) return v;
    const prefixes = ['Tech', 'Global', 'Digital', 'Smart', 'Innovative', 'Advanced'];
    const suffixes = ['Solutions', 'Systems', 'Corp', 'Industries', 'Group', 'Enterprises'];
    return `${prefixes[Math.floor(Math.random() * prefixes.length)]} ${suffixes[Math.floor(Math.random() * suffixes.length)]}`;
  },
  jobTitle: () => {
    const v = getPatternValue('job_title') || getPatternValue('position') || getPatternValue('role');
    if (v) return v;
    const titles = ['Software Engineer', 'Product Manager', 'Data Analyst', 'Sales Manager', 'Marketing Director', 'Account Executive', 'Business Analyst', 'Project Manager', 'Developer', 'Designer'];
    return titles[Math.floor(Math.random() * titles.length)];
  },
  department: () => {
    const v = getPatternValue('department') || getPatternValue('dept');
    if (v) return v;
    const depts = ['Engineering', 'Sales', 'Marketing', 'Finance', 'Human Resources', 'Operations', 'Customer Service', 'IT', 'Legal', 'R&D'];
    return depts[Math.floor(Math.random() * depts.length)];
  },
  creditCard: () => {
    const parts = [];
    for (let i = 0; i < 4; i++) parts.push(Math.floor(Math.random() * 9000) + 1000);
    return parts.join('-');
  },
  currency: () => {
    const v = getPatternValue('currency') || getPatternValue('currency_code');
    if (v) return v;
    return ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD', 'CHF', 'CNY'][Math.floor(Math.random() * 8)];
  },
  amount: () => (Math.random() * 10000).toFixed(2),
  iban: () => {
    const country = ['GB', 'DE', 'FR', 'IT', 'ES'][Math.floor(Math.random() * 5)];
    const check = Math.floor(Math.random() * 90) + 10;
    const bank = Math.floor(Math.random() * 9000) + 1000;
    const account = Math.floor(Math.random() * 90000000) + 10000000;
    return `${country}${check}${bank}${account}`;
  },
  uuid: () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  }),
  ipAddress: () => `${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}`,
  url: () => `https://www.${['example.com', 'website.org', 'demo.net', 'test.io', 'sample.dev'][Math.floor(Math.random() * 5)]}`,
  username: () => generators.firstName().toLowerCase() + Math.floor(Math.random() * 9999),
  date: () => {
    const start = new Date(2020, 0, 1);
    const end = new Date();
    return new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime())).toISOString().split('T')[0];
  },
  datetime: () => {
    const start = new Date(2020, 0, 1);
    const end = new Date();
    return new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime())).toISOString();
  },
  birthdate: () => {
    const year = 1950 + Math.floor(Math.random() * 50);
    const month = Math.floor(Math.random() * 12) + 1;
    const day = Math.floor(Math.random() * 28) + 1;
    return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  },
  integer: () => Math.floor(Math.random() * 10000),
  decimal: () => (Math.random() * 1000).toFixed(2),
  percentage: () => (Math.random() * 100).toFixed(1)
};

// ============================================
// STEP 4: Intelligent value generator (pattern-first)
// ============================================
function generateIntelligentValue(fieldName, fieldType) {
  const nameLower = fieldName.toLowerCase();
  const typeLower = (fieldType || '').toLowerCase();
  const patternValue = getPatternValue(fieldName);
  if (patternValue) return patternValue;
  if (nameLower.includes('customer_id') || (nameLower.includes('id') && typeLower === 'int')) return Math.floor(Math.random() * 10000) + 1;
  if (nameLower.includes('first_name') || nameLower === 'firstname') return generators.firstName();
  if (nameLower.includes('last_name') || nameLower === 'lastname') return generators.lastName();
  if (nameLower.includes('full_name') || nameLower === 'name' || (nameLower.includes('name') && !nameLower.includes('first') && !nameLower.includes('last'))) return `${generators.firstName()} ${generators.lastName()}`;
  if (nameLower.includes('city')) return generators.city();
  if (nameLower.includes('email')) return generators.email();
  if (nameLower.includes('date') || nameLower.includes('time')) return typeLower === 'date' ? generators.date() : generators.datetime();
  if (typeLower === 'int' || typeLower === 'integer') return generators.integer();
  if (typeLower === 'decimal' || typeLower === 'float') return generators.decimal();
  if (typeLower === 'uuid') return generators.uuid();
  const g = generators[fieldType] || generators[typeLower];
  if (g) return g();
  return `${fieldType}_value`;
}

// ============================================
// STEP 5: Generate data
// ============================================
const data = [];
for (let i = 0; i < recordCount; i++) {
  const record = {};
  schema.forEach(field => {
    const blankPercentage = field.blankPercentage || 0;
    const shouldBeBlank = Math.random() * 100 < blankPercentage;
    if (shouldBeBlank) {
      record[field.name] = null;
    } else {
      const patternValue = getPatternValue(field.name);
      record[field.name] = patternValue !== null ? patternValue : generateIntelligentValue(field.name, field.type);
    }
  });
  data.push(record);
}

return [{
  json: {
    success: true,
    data: data,
    recordCount: data.length,
    exportFormat: exportFormat
  }
}];
